from pathlib import Path

path = Path("src/script/fetch_api.rs")
text = path.read_text()

old = "use std::rc::Rc;"
new = "use std::rc::{Rc, Weak};"
assert old in text
text = text.replace(old, new, 1)

anchor = '''/// The schemes a page may fetch, on top of its own.\nconst FETCHABLE_SCHEMES: &[&str] = &["http", "https", "file"];\n'''
insert = '''/// The schemes a page may fetch, on top of its own.\nconst FETCHABLE_SCHEMES: &[&str] = &["http", "https", "file"];\n\n/// Fetch defaults preflight permissions to five seconds when Max-Age is absent\n/// or invalid. A user agent may impose its own upper bound.\nconst DEFAULT_CORS_PREFLIGHT_MAX_AGE_SECS: u64 = 5;\nconst MAX_CORS_PREFLIGHT_MAX_AGE_SECS: u64 = 7_200;\nconst MAX_CORS_PREFLIGHT_CACHE_ENTRIES_PER_SESSION: usize = 256;\n\n#[derive(Debug, Clone)]\nstruct CorsPreflightCacheEntry {\n    source_origin: String,\n    target_url: String,\n    credentialed: bool,\n    allowed_methods: Vec<String>,\n    allowed_headers: Vec<String>,\n    expires_at_ms: u64,\n}\n\n#[derive(Debug)]\nstruct CorsPreflightSessionCache {\n    /// Browser documents in one session share a CookieJar. A weak handle gives\n    /// the preflight cache the same lifetime without keeping dead sessions alive.\n    jar: Weak<RefCell<crate::cookie::CookieJar>>,\n    entries: Vec<CorsPreflightCacheEntry>,\n}\n\nthread_local! {\n    static CORS_PREFLIGHT_CACHES: RefCell<Vec<CorsPreflightSessionCache>> = RefCell::new(Vec::new());\n}\n\nfn with_cors_preflight_session_cache<R>(\n    jar: &Rc<RefCell<crate::cookie::CookieJar>>,\n    operation: impl FnOnce(&mut Vec<CorsPreflightCacheEntry>) -> R,\n) -> R {\n    CORS_PREFLIGHT_CACHES.with(|sessions| {\n        let mut sessions = sessions.borrow_mut();\n        sessions.retain(|session| session.jar.upgrade().is_some());\n        let index = sessions\n            .iter()\n            .position(|session| {\n                session\n                    .jar\n                    .upgrade()\n                    .is_some_and(|live| Rc::ptr_eq(&live, jar))\n            })\n            .unwrap_or_else(|| {\n                sessions.push(CorsPreflightSessionCache {\n                    jar: Rc::downgrade(jar),\n                    entries: Vec::new(),\n                });\n                sessions.len() - 1\n            });\n        operation(&mut sessions[index].entries)\n    })\n}\n'''
assert anchor in text
text = text.replace(anchor, insert, 1)

old = '''                    let needs_preflight = cors\n                        .as_ref()\n                        .is_some_and(|state| state.needs_preflight);\n'''
new = '''                    let needs_preflight = match cors.as_ref() {\n                        Some(state) if state.needs_preflight => {\n                            !self.cors_preflight_cache_allows(&request, state)\n                        }\n                        _ => false,\n                    };\n'''
assert old in text
text = text.replace(old, new, 1)

old = '''                if let Err(error) = validate_cors_preflight_response(&cors, &response) {\n                    self.reject_with(&promise, &error);\n                    return;\n                }\n\n                let wire = request.to_wire();\n'''
new = '''                if let Err(error) = validate_cors_preflight_response(&cors, &response) {\n                    self.reject_with(&promise, &error);\n                    return;\n                }\n                self.store_cors_preflight_permissions(&request, &cors, &response);\n\n                let wire = request.to_wire();\n'''
assert old in text
text = text.replace(old, new, 1)

anchor = '''    fn queue_fetch(\n        &mut self,\n        request: FetchRequest,\n        pending: PendingFetch,\n        cookie_policy: CookieRequestPolicy,\n    ) -> Result<(), FetchError> {\n'''
insert = '''    fn cors_preflight_cache_allows(\n        &self,\n        request: &RequestData,\n        cors: &CorsFetchState,\n    ) -> bool {\n        let now_ms = self\n            .cookie_jar\n            .borrow()\n            .effective_now_ms(self.now_ms.max(0.0) as u64);\n        let source_origin = cors.source_origin.header_value();\n        let target_url = request.url.without_fragment().to_string();\n\n        with_cors_preflight_session_cache(&self.cookie_jar, |entries| {\n            entries.retain(|entry| entry.expires_at_ms > now_ms);\n            entries.iter().any(|entry| {\n                if entry.source_origin != source_origin\n                    || entry.target_url != target_url\n                    || (!entry.credentialed && cors.credentialed)\n                {\n                    return false;\n                }\n\n                let method_allowed = is_cors_safelisted_method(cors.requested_method)\n                    || entry.allowed_methods.iter().any(|method| {\n                        method == cors.requested_method.as_str()\n                            || (method == "*" && !cors.credentialed)\n                    });\n                method_allowed\n                    && cors.requested_headers.iter().all(|requested| {\n                        entry.allowed_headers.iter().any(|allowed| {\n                            allowed.eq_ignore_ascii_case(requested)\n                                || (allowed == "*"\n                                    && !cors.credentialed\n                                    && !is_cors_non_wildcard_request_header_name(requested))\n                        })\n                    })\n            })\n        })\n    }\n\n    fn store_cors_preflight_permissions(\n        &self,\n        request: &RequestData,\n        cors: &CorsFetchState,\n        response: &FetchResponse,\n    ) {\n        let max_age = cors_preflight_max_age_seconds(response);\n        if max_age == 0 {\n            return;\n        }\n\n        let now_ms = self\n            .cookie_jar\n            .borrow()\n            .effective_now_ms(self.now_ms.max(0.0) as u64);\n        let source_origin = cors.source_origin.header_value();\n        let target_url = request.url.without_fragment().to_string();\n        let expires_at_ms = now_ms.saturating_add(max_age.saturating_mul(1_000));\n        let allowed_methods = comma_tokens(response.headers.get("access-control-allow-methods"));\n        let allowed_headers = comma_tokens(response.headers.get("access-control-allow-headers"));\n\n        with_cors_preflight_session_cache(&self.cookie_jar, |entries| {\n            entries.retain(|entry| {\n                entry.expires_at_ms > now_ms\n                    && (entry.source_origin != source_origin\n                        || entry.target_url != target_url\n                        || entry.credentialed != cors.credentialed)\n            });\n            if entries.len() >= MAX_CORS_PREFLIGHT_CACHE_ENTRIES_PER_SESSION {\n                entries.remove(0);\n            }\n            entries.push(CorsPreflightCacheEntry {\n                source_origin,\n                target_url,\n                credentialed: cors.credentialed,\n                allowed_methods,\n                allowed_headers,\n                expires_at_ms,\n            });\n        });\n    }\n\n    fn queue_fetch(\n        &mut self,\n        request: FetchRequest,\n        pending: PendingFetch,\n        cookie_policy: CookieRequestPolicy,\n    ) -> Result<(), FetchError> {\n'''
assert anchor in text
text = text.replace(anchor, insert, 1)

anchor = '''fn comma_tokens(value: Option<String>) -> Vec<String> {\n'''
insert = '''fn cors_preflight_max_age_seconds(response: &FetchResponse) -> u64 {\n    response\n        .headers\n        .get("access-control-max-age")\n        .and_then(|value| value.trim().parse::<u64>().ok())\n        .unwrap_or(DEFAULT_CORS_PREFLIGHT_MAX_AGE_SECS)\n        .min(MAX_CORS_PREFLIGHT_MAX_AGE_SECS)\n}\n\nfn is_cors_non_wildcard_request_header_name(name: &str) -> bool {\n    name.eq_ignore_ascii_case("authorization")\n}\n\nfn comma_tokens(value: Option<String>) -> Vec<String> {\n'''
assert anchor in text
text = text.replace(anchor, insert, 1)
path.write_text(text)

Path("tests/fetch_cors_preflight_cache.rs").write_text(r'''use std::rc::Rc;\nuse std::time::Duration;\n\nuse browser_engine::browser::Browser;\nuse browser_engine::eventloop::ManualClock;\nuse browser_engine::net::{FetchResponse, ManualNetwork, MemoryLoader, Url};\n\nfn url(input: &str) -> Url {\n    Url::parse(input).expect("valid URL")\n}\n\nfn response(\n    endpoint: &str,\n    max_age: &str,\n    methods: &str,\n    headers: &str,\n    credentialed: bool,\n) -> FetchResponse {\n    let mut response = FetchResponse::synthetic(\n        url(endpoint),\n        200,\n        Some("text/plain"),\n        b"ok".to_vec(),\n    );\n    response.headers.append_raw(\n        "access-control-allow-origin",\n        if credentialed { "http://page.test" } else { "*" },\n    );\n    response\n        .headers\n        .append_raw("access-control-allow-methods", methods);\n    response\n        .headers\n        .append_raw("access-control-allow-headers", headers);\n    response\n        .headers\n        .append_raw("access-control-max-age", max_age);\n    if credentialed {\n        response\n            .headers\n            .append_raw("access-control-allow-credentials", "true");\n    }\n    response\n}\n\nfn browser_for(\n    script: &str,\n    endpoint: &str,\n    response: FetchResponse,\n) -> (Browser, Rc<ManualNetwork>) {\n    let page = "http://page.test/index.html";\n    let mut loader = MemoryLoader::new();\n    loader.insert(page, format!("<script>{script}</script>"));\n    let transport = Rc::new(ManualNetwork::new());\n    transport.respond(endpoint, response);\n    let browser = Browser::open_with_network(\n        Box::new(loader),\n        transport.clone(),\n        &url(page),\n        Rc::new(ManualClock::new()),\n    )\n    .expect("page loads");\n    (browser, transport)\n}\n\nfn drive(browser: &mut Browser, transport: &Rc<ManualNetwork>) {\n    for _ in 0..12 {\n        browser.tick();\n        transport.complete_all();\n    }\n    browser.tick();\n}\n\nfn methods(transport: &ManualNetwork) -> Vec<String> {\n    transport\n        .requests()\n        .iter()\n        .map(|request| request.method.as_str().to_string())\n        .collect()\n}\n\n#[test]\nfn positive_max_age_reuses_preflight_for_an_identical_request() {\n    let endpoint = "http://api.test/data";\n    let script = r#"\n        fetch("http://api.test/data", { method: "PUT", headers: { "X-Token": "one" }, body: "a" })\n          .then(function () { return fetch("http://api.test/data", { method: "PUT", headers: { "X-Token": "two" }, body: "b" }); })\n          .then(function () { console.log("done"); }).catch(function () { console.log("blocked"); });\n    "#;\n    let (mut browser, transport) = browser_for(\n        script,\n        endpoint,\n        response(endpoint, "60", "PUT", "x-token", false),\n    );\n\n    drive(&mut browser, &transport);\n\n    assert_eq!(methods(&transport), vec!["OPTIONS", "PUT", "PUT"]);\n    assert_eq!(browser.document().runtime.console, vec!["done"]);\n}\n\n#[test]\nfn cache_reuses_all_permissions_granted_by_the_preflight_response() {\n    let endpoint = "http://api.test/data";\n    let script = r#"\n        fetch("http://api.test/data", { method: "PUT", headers: { "X-Token": "one" }, body: "a" })\n          .then(function () { return fetch("http://api.test/data", { method: "PATCH", headers: { "X-Other": "two" }, body: "b" }); })\n          .then(function () { console.log("done"); });\n    "#;\n    let (mut browser, transport) = browser_for(\n        script,\n        endpoint,\n        response(endpoint, "60", "PUT, PATCH", "x-token, x-other", false),\n    );\n\n    drive(&mut browser, &transport);\n\n    assert_eq!(methods(&transport), vec!["OPTIONS", "PUT", "PATCH"]);\n    assert_eq!(browser.document().runtime.console, vec!["done"]);\n}\n\n#[test]\nfn max_age_zero_forces_the_next_request_to_preflight_again() {\n    let endpoint = "http://api.test/data";\n    let script = r#"\n        fetch("http://api.test/data", { method: "PUT", headers: { "X-Token": "one" }, body: "a" })\n          .then(function () { return fetch("http://api.test/data", { method: "PUT", headers: { "X-Token": "two" }, body: "b" }); })\n          .then(function () { console.log("done"); });\n    "#;\n    let (mut browser, transport) = browser_for(\n        script,\n        endpoint,\n        response(endpoint, "0", "PUT", "x-token", false),\n    );\n\n    drive(&mut browser, &transport);\n\n    assert_eq!(methods(&transport), vec!["OPTIONS", "PUT", "OPTIONS", "PUT"]);\n}\n\n#[test]\nfn expired_entry_is_not_reused_after_the_session_clock_advances() {\n    let endpoint = "http://api.test/data";\n    let script = r#"\n        fetch("http://api.test/data", { method: "PUT", headers: { "X-Token": "one" }, body: "a" })\n          .then(function () {\n              setTimeout(function () {\n                  fetch("http://api.test/data", { method: "PUT", headers: { "X-Token": "two" }, body: "b" });\n              }, 1100);\n          });\n    "#;\n    let (mut browser, transport) = browser_for(\n        script,\n        endpoint,\n        response(endpoint, "1", "PUT", "x-token", false),\n    );\n\n    browser.tick();\n    assert_eq!(transport.complete_all(), 1);\n    browser.tick();\n    assert_eq!(transport.complete_all(), 1);\n    browser.tick();\n    assert_eq!(methods(&transport), vec!["OPTIONS", "PUT"]);\n\n    browser.advance_time(Duration::from_millis(1100));\n    browser.tick();\n\n    assert_eq!(methods(&transport), vec!["OPTIONS", "PUT", "OPTIONS"]);\n}\n\n#[test]\nfn noncredentialed_entry_does_not_authorize_a_later_credentialed_request() {\n    let endpoint = "http://api.test/data";\n    let script = r#"\n        fetch("http://api.test/data", { method: "PUT", headers: { "X-Token": "one" }, body: "a", credentials: "omit" })\n          .then(function () { return fetch("http://api.test/data", { method: "PUT", headers: { "X-Token": "two" }, body: "b", credentials: "include" }); });\n    "#;\n    let (mut browser, transport) = browser_for(\n        script,\n        endpoint,\n        response(endpoint, "60", "PUT", "x-token", true),\n    );\n\n    drive(&mut browser, &transport);\n\n    assert_eq!(methods(&transport), vec!["OPTIONS", "PUT", "OPTIONS", "PUT"]);\n}\n\n#[test]\nfn authorization_is_not_satisfied_by_allow_headers_wildcard() {\n    let endpoint = "http://api.test/data";\n    let script = r#"\n        fetch("http://api.test/data", { method: "PUT", headers: { "X-Token": "one" }, body: "a" })\n          .then(function () { return fetch("http://api.test/data", { method: "PUT", headers: { "Authorization": "Bearer x" }, body: "b" }); });\n    "#;\n    let (mut browser, transport) = browser_for(\n        script,\n        endpoint,\n        response(endpoint, "60", "*", "*", false),\n    );\n\n    drive(&mut browser, &transport);\n\n    assert_eq!(methods(&transport), vec!["OPTIONS", "PUT", "OPTIONS"]);\n}\n''')
